// --- VERSION 0.0.1.0 ---
// - New full-screen single-log replay page with speed-colored track,
//   live gauges, 3 PID selectors, overlay chart, and playback controls.

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { MapContainer, TileLayer, Polyline, CircleMarker, useMap } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend
} from 'chart.js';
import zoomPlugin from 'chartjs-plugin-zoom';
ChartJS.register(zoomPlugin);


ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

const TILE_URL = "https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}.png";

function clamp(val, min, max) {
  return Math.max(min, Math.min(max, val));
}

function colorForSpeed(mph) {
  // Blue at 0 mph -> green at ~30 -> yellow at ~60 -> red at >= 80
  if (mph <= 0) return '#3B82F6';
  if (mph < 30) return '#22C55E';
  if (mph < 60) return '#F59E0B';
  if (mph < 80) return '#FB923C';
  return '#EF4444';
}

const minSpeed = Math.min(...log.data.map(r => Number(r.gps_speed) || 0));
const maxSpeed = Math.max(...log.data.map(r => Number(r.gps_speed) || 0));

function colorForSpeedDynamic(mph) {
  const ratio = (mph - minSpeed) / (maxSpeed - minSpeed || 1);
  // interpolate blue → green → yellow → red
  if (ratio <= 0.25) return '#3B82F6';
  if (ratio <= 0.5) return '#22C55E';
  if (ratio <= 0.75) return '#F59E0B';
  return '#EF4444';
}

function computeBounds(points) {
  if (!points.length) return [[44.97, -93.26], [44.98, -93.27]];
  const lats = points.map(p => p[0]);
  const lons = points.map(p => p[1]);
  const minLat = Math.min(...lats), maxLat = Math.max(...lats);
  const minLon = Math.min(...lons), maxLon = Math.max(...lons);
  const padLat = (maxLat - minLat) * 0.1 || 0.0005;
  const padLon = (maxLon - minLon) * 0.1 || 0.0005;
  return [[minLat - padLat, minLon - padLon], [maxLat + padLat, maxLon + padLon]];
}

function trimIdleEnds(rows, latKey, lonKey, speedKey) {
  // Trim leading/trailing zero or near-zero speed segments (>10s consecutive)
  if (!Array.isArray(rows) || rows.length === 0) return rows;

  const speed = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
  };

  // Average speed in mph
const avgSpeed = log.data.reduce((sum, r) => sum + (Number(r.gps_speed) || 0), 0) / log.data.length;
let zoom;
if (avgSpeed < 15) zoom = 17;
else if (avgSpeed < 35) zoom = 16;
else if (avgSpeed < 55) zoom = 15;
else zoom = 14;
map.easeTo({ center: cursorPos, zoom, bearing: heading });

  // Determine interval (sec)
  let intervalSec = 1;
  if (rows.length > 1 && rows[0]?.timestamp != null && rows[1]?.timestamp != null) {
    const d = Math.abs(Number(rows[1].timestamp) - Number(rows[0].timestamp));
    intervalSec = d > 1000 ? d / 1000 : (d || 1);
  }

  const thresholdMph = 1.0;
  const idleThresholdSec = 10;
  const idleCount = Math.ceil(idleThresholdSec / intervalSec);

  // Leading
  let startIdx = 0;
  while (startIdx + idleCount < rows.length) {
    let allIdle = true;
    for (let i = 0; i < idleCount; i++) {
      const row = rows[startIdx + i];
      const lat = Number(row?.[latKey] ?? 0);
      const lon = Number(row?.[lonKey] ?? 0);
      if (!Number.isFinite(lat) || !Number.isFinite(lon) || lat === 0 || lon === 0) { continue; }
      if (speed(row?.[speedKey]) > thresholdMph) { allIdle = false; break; }
    }
    if (allIdle) startIdx += 1; else break;
  }

  // Trailing
  let endIdx = rows.length - 1;
  while (endIdx - idleCount >= startIdx) {
    let allIdle = true;
    for (let i = 0; i < idleCount; i++) {
      const row = rows[endIdx - i];
      const lat = Number(row?.[latKey] ?? 0);
      const lon = Number(row?.[lonKey] ?? 0);
      if (!Number.isFinite(lat) || !Number.isFinite(lon) || lat === 0 || lon === 0) { continue; }
      if (speed(row?.[speedKey]) > thresholdMph) { allIdle = false; break; }
    }
    if (allIdle) endIdx -= 1; else break;
  }

  if (startIdx >= endIdx) return rows;
  return rows.slice(startIdx, endIdx + 1);
}

function MapFitter({ bounds }) {
  const map = useMap();
  useEffect(() => {
    if (bounds && bounds[0] && bounds[1]) {
      map.fitBounds(bounds, { padding: [20, 20], animate: true, duration: 0.4 });
    }
  }, [bounds, map]);
  return null;
}

export default function DriveReplay() {
  const { logId } = useParams();
  const [raw, setRaw] = useState(null);
  const [log, setLog] = useState(null);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState(null);

  // PID selectors: default 3
  const [selectedPIDs, setSelectedPIDs] = useState(['gps_speed', 'engine_rpm', 'instant_fuel_economy']);

  // Playback state
  const [playState, setPlayState] = useState({ playing: false, rate: 1 }); // rate: -5,-2,-1,0,1,2,5
  const [cursorIdx, setCursorIdx] = useState(0);
  const timerRef = useRef(null);

  // Fetch data
  useEffect(() => {
    let mounted = true;
    setLoading(true);
    setErr(null);
    fetch(`/api/logs/${logId}/data`)
      .then(res => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then(data => {
        if (!mounted) return;
        const rows = Array.isArray(data?.data) ? data.data : [];
        const columns = Array.isArray(data?.columns) ? data.columns : (rows.length ? Object.keys(rows[0]) : []);
        const trimmed = trimIdleEnds(rows, 'latitude', 'longitude', 'gps_speed');
        setRaw(data);
        setLog({ data: trimmed, columns });
        setCursorIdx(0);
      })
      .catch(e => {
        if (!mounted) return;
        setErr(e.message || 'Failed to load');
      })
      .finally(() => mounted && setLoading(false));
    return () => { mounted = false; };
  }, [logId]);

  const points = useMemo(() => {
    if (!log?.data) return [];
    return log.data
      .map(r => [Number(r?.latitude ?? 0), Number(r?.longitude ?? 0)])
      .filter(([lat, lon]) => Number.isFinite(lat) && Number.isFinite(lon) && lat !== 0 && lon !== 0);
  }, [log]);

  const bounds = useMemo(() => computeBounds(points), [points]);

  // Build speed-segment polylines
  const segments = useMemo(() => {
    if (!log?.data || points.length < 2) return [];
    const segs = [];
    for (let i = 1; i < points.length; i++) {
      const sp = Number(log.data[i]?.gps_speed ?? 0);
      const color = colorForSpeed(sp);
      segs.push({ pts: [points[i - 1], points[i]], color });
    }
    return segs;
  }, [log, points]);

  // Chart datasets (no sampling)
  const chartData = useMemo(() => {
    if (!log?.data) return { labels: [], datasets: [] };
    const labels = log.data.map((row, i) => i);
    const datasets = selectedPIDs
      .filter(pid => pid && pid !== 'none')
      .map((pid, i) => ({
        label: pid,
        data: log.data.map(r => {
          const val = r?.[pid];
          const n = Number(val);
          return Number.isFinite(n) ? n : null;
        }),
        borderColor: ['#38BDF8', '#F59E0B', '#A78BFA', '#22C55E', '#EF4444'][i % 5],
        backgroundColor: 'transparent',
        borderWidth: 2,
        pointRadius: 0,
        tension: 0.3,
      }));
    return { labels, datasets };
  }, [log, selectedPIDs]);

  const chartOptions = useMemo(() => ({
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: { display: true, labels: { color: '#9CA3AF' } },
      tooltip: { enabled: true }
    },
    scales: {
      x: { ticks: { color: '#9CA3AF' } },
      y: { ticks: { color: '#9CA3AF' } }
    }
  }), []);

  // Telemetry at cursor
  const currentRow = useMemo(() => log?.data?.[cursorIdx] || null, [log, cursorIdx]);
  const gpsSpeed = Number(currentRow?.gps_speed ?? currentRow?.vehicle_speed ?? 0);
  const volts = Number(currentRow?.adapter_voltage ?? 0);
  const rpm = Number(currentRow?.engine_rpm ?? 0);
  const mpg = Number(currentRow?.instant_fuel_economy ?? currentRow?.instant_fuel_economy_mpg ?? 0);

  // Cursor position
  const cursorPos = useMemo(() => {
    if (!log?.data) return null;
    const row = log.data[cursorIdx];
    if (!row) return null;
    const lat = Number(row?.latitude ?? 0);
    const lon = Number(row?.longitude ?? 0);
    return (Number.isFinite(lat) && Number.isFinite(lon) && lat !== 0 && lon !== 0) ? [lat, lon] : null;
  }, [log, cursorIdx]);

  // Playback timer
  useEffect(() => {
    if (!log?.data || log.data.length < 2) return;
    if (!playState.playing || playState.rate === 0) return;

    const step = () => {
      // Determine step size based on playback rate and target per-frame advancement
      const dir = Math.sign(playState.rate);
      const mag = Math.abs(playState.rate);
      // Scale logical steps (approximate real-time smoothing)
      const baseStep = mag; // 1,2,5 indices per tick
      setCursorIdx(prev => {
        const next = clamp(prev + dir * baseStep, 0, log.data.length - 1);
        return next;
      });
    };

    // Timer frequency ~ 50ms for smoother animation
    timerRef.current = setInterval(step, 50);
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      timerRef.current = null;
    };
  }, [playState, log]);

  // Controls
  const setRate = useCallback((rate) => setPlayState(s => ({ ...s, rate })), []);
  const playPause = useCallback(() => setPlayState(s => ({ ...s, playing: !s.playing })), []);
  const stop = useCallback(() => {
    setPlayState({ playing: false, rate: 0 });
    setCursorIdx(0);
  }, []);
  const stepRelative = useCallback((dx) => {
    setPlayState(s => ({ ...s, playing: false, rate: 0 }));
    setCursorIdx(prev => clamp(prev + dx, 0, (log?.data?.length ?? 1) - 1));
  }, [log]);

  // Keyboard shortcuts
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === ' ') { e.preventDefault(); playPause(); }
      else if (e.key === 'ArrowRight') stepRelative(+5);
      else if (e.key === 'ArrowLeft') stepRelative(-5);
      else if (e.key === '1') setRate(1);
      else if (e.key === '2') setRate(2);
      else if (e.key === '5') setRate(5);
      else if (e.key === 'q') setRate(-1);
      else if (e.key === 'w') setRate(-2);
      else if (e.key === 'e') setRate(-5);
      else if (e.key === '0') setRate(0);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [playPause, stepRelative, setRate]);

  const handlePidChange = useCallback((idx, val) => {
    setSelectedPIDs(prev => {
      const next = [...prev];
      next[idx] = val;
      return next;
    });
  }, []);

  if (loading) {
    return (
      <div className="w-screen h-screen bg-gray-900 text-gray-300 flex items-center justify-center">
        <div>
          <div className="animate-spin w-10 h-10 border-4 border-cyan-400 border-t-transparent rounded-full mx-auto mb-4"></div>
          Loading replay...
        </div>
      </div>
    );
  }

  if (err || !log?.data?.length) {
    return (
      <div className="w-screen h-screen bg-gray-900 text-gray-300 flex items-center justify-center">
        <div className="text-center">
          <div className="text-red-400 font-semibold mb-2">Unable to load log</div>
          <div className="text-sm text-gray-400 mb-4">{err || 'No data'}</div>
          <Link to={`/logs/${logId}`} className="text-cyan-400 hover:text-cyan-300 underline">Back to Log</Link>
        </div>
      </div>
    );
  }

  const pidOptions = log.columns;

  return (
    <div className="w-screen h-screen bg-gray-900 text-white overflow-hidden relative">
      {/* Top overlay: controls + file link */}
      <div className="absolute top-0 left-0 right-0 z-20 bg-gray-900/70 backdrop-blur px-4 py-2 flex items-center gap-3">
        <Link to={`/logs/${logId}`} className="text-cyan-400 hover:text-cyan-300 underline">← Back</Link>
        <div className="flex items-center gap-2 text-sm">
          <button onClick={playPause} className="px-2 py-1 bg-gray-700 rounded hover:bg-gray-600">
            {playState.playing ? 'Pause' : 'Play'}
          </button>
          <button onClick={stop} className="px-2 py-1 bg-gray-700 rounded hover:bg-gray-600">Stop</button>
          <button onClick={() => setRate(-5)} className={`px-2 py-1 rounded ${playState.rate===-5?'bg-cyan-700':'bg-gray-700 hover:bg-gray-600'}`}>-5x</button>
          <button onClick={() => setRate(-2)} className={`px-2 py-1 rounded ${playState.rate===-2?'bg-cyan-700':'bg-gray-700 hover:bg-gray-600'}`}>-2x</button>
          <button onClick={() => setRate(-1)} className={`px-2 py-1 rounded ${playState.rate===-1?'bg-cyan-700':'bg-gray-700 hover:bg-gray-600'}`}>-1x</button>
          <button onClick={() => setRate(0)} className={`px-2 py-1 rounded ${playState.rate===0?'bg-cyan-700':'bg-gray-700 hover:bg-gray-600'}`}>0x</button>
          <button onClick={() => setRate(1)} className={`px-2 py-1 rounded ${playState.rate===1?'bg-cyan-700':'bg-gray-700 hover:bg-gray-600'}`}>1x</button>
          <button onClick={() => setRate(2)} className={`px-2 py-1 rounded ${playState.rate===2?'bg-cyan-700':'bg-gray-700 hover:bg-gray-600'}`}>2x</button>
          <button onClick={() => setRate(5)} className={`px-2 py-1 rounded ${playState.rate===5?'bg-cyan-700':'bg-gray-700 hover:bg-gray-600'}`}>5x</button>
          <div className="ml-2 text-gray-400">Space: Play/Pause • ←/→: step • 1/2/5 & q/w/e: rate</div>
        </div>
      </div>

      {/* Map */}
      <div className="fixed top-0 left-0 w-screen h-screen z-0">
        <MapContainer bounds={bounds} style={{ width: '100%', height: '100%' }} zoomControl={false}>
          <MapFitter bounds={bounds} />
          <TileLayer url={TILE_URL} />
          {/* Context path */}
          {points.length > 1 && (
            <Polyline positions={points} color="#374151" weight={2} opacity={0.5} />
          )}
          {/* Speed-colored segments */}
          {segments.map((s, i) => (
            <Polyline key={i} positions={s.pts} color={s.color} weight={4} opacity={0.9} />
          ))}
          {/* Cursor marker */}
          {cursorPos && (
            <CircleMarker center={cursorPos} radius={5} color="#FFFFFF" weight={2} fillOpacity={0.9} />
          )}
        </MapContainer>
      </div>

      {/* Gauges overlay */}
      <div className="absolute bottom-4 left-4 z-20 grid grid-cols-2 md:grid-cols-4 gap-3">
        <div className="bg-gray-800/90 rounded p-3 min-w-[130px]">
          <div className="text-xs text-gray-400">GPS Speed</div>
          <div className="text-3xl font-bold" style={{ color: colorForSpeed(gpsSpeed) }}>
            {Number.isFinite(gpsSpeed) ? gpsSpeed.toFixed(0) : '—'}<span className="text-base text-gray-400"> mph</span>
          </div>
        </div>
        <div className="bg-gray-800/90 rounded p-3 min-w-[130px]">
          <div className="text-xs text-gray-400">Engine RPM</div>
          <div className="text-3xl font-bold text-cyan-300">
            {Number.isFinite(rpm) ? rpm.toFixed(0) : '—'}
          </div>
        </div>
        <div className="bg-gray-800/90 rounded p-3 min-w-[130px]">
          <div className="text-xs text-gray-400">Adapter Volts</div>
          <div className="text-3xl font-bold text-amber-300">
            {Number.isFinite(volts) ? volts.toFixed(1) : '—'}<span className="text-base text-gray-400"> V</span>
          </div>
        </div>
        <div className="bg-gray-800/90 rounded p-3 min-w-[130px]">
          <div className="text-xs text-gray-400">Instant MPG</div>
          <div className="text-3xl font-bold text-emerald-300">
            {Number.isFinite(mpg) ? mpg.toFixed(1) : '—'}
          </div>
        </div>
      </div>

      {/* Mini compass + position */}
      <div className="absolute top-14 left-4 z-20 bg-gray-800/90 rounded p-2 text-xs text-gray-300">
        <div className="font-mono">
          Index {cursorIdx + 1}/{log.data.length}
        </div>
        <div className="font-mono">
          Lat/Lon: {cursorPos ? `${cursorPos[0].toFixed(5)}, ${cursorPos[1].toFixed(5)}` : '—'}
        </div>
      </div>

      {/* PID selectors + chart overlay (top-right) */}
      <div className="absolute top-12 right-4 z-20 bg-gray-900/90 rounded-lg p-3 w-[32vw] min-w-[320px] h-[28vh]">
        <div className="flex gap-2 mb-2">
          {selectedPIDs.map((pid, i) => (
            <select
              key={i}
              className="bg-gray-700 text-gray-100 text-xs px-2 py-1 rounded w-1/3"
              value={pid}
              onChange={(e) => handlePidChange(i, e.target.value)}
            >
              <option value="none">none</option>
              {pidOptions.map(opt => (
                <option key={opt} value={opt}>{opt}</option>
              ))}
            </select>
          ))}
        </div>
        <div className="w-full h-[22vh]">
          <Line data={chartData} options={chartOptions} />
        </div>
      </div>

      {/* Scrub bar (bottom center) */}
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 z-20 w-[60vw] min-w-[320px]">
        <input
          type="range"
          min="0"
          max={(log.data.length - 1).toString()}
          value={cursorIdx}
          onChange={(e) => { setPlayState(s => ({ ...s, playing: false })); setCursorIdx(Number(e.target.value)); }}
          className="w-full accent-cyan-400"
        />
      </div>
    </div>
  );
}
